/**
 * @name SQL injection vulnerability
 * @description User input flowing into SQL queries without proper sanitization
 * @kind path-problem
 * @problem.severity error
 * @id py/sql-injection
 * @tags security
 *        external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module SqlInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Use API graphs to find SQL execution calls
    exists(API::CallNode call |
      // Common SQL execution patterns
      (
        // Direct SQL execution calls
        call = API::moduleImport("sqlite3").getMember("connect").getReturn().getMember("execute").getACall() or
        call = API::moduleImport("sqlite3").getMember("Cursor").getMember("execute").getACall() or
        call = API::moduleImport("mysql").getMember("connector").getMember("connect").getReturn().getMember("cursor").getReturn().getMember("execute").getACall() or
        call = API::moduleImport("psycopg2").getMember("connect").getReturn().getMember("cursor").getReturn().getMember("execute").getACall() or
        call = API::moduleImport("pymysql").getMember("connect").getReturn().getMember("cursor").getReturn().getMember("execute").getACall() or
        call = API::moduleImport("sqlalchemy").getMember("text").getACall() or
        call = API::moduleImport("sqlalchemy").getMember("create_engine").getReturn().getMember("execute").getACall()
      ) and
      // Get the first argument (SQL query) as a DataFlow::Node
      sink = call.getArg(0)
    )
  }
}

module SqlInjectionFlow = TaintTracking::Global<SqlInjectionConfig>;
import SqlInjectionFlow::PathGraph

from SqlInjectionFlow::PathNode source, SqlInjectionFlow::PathNode sink
where SqlInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SQL injection from $@.", source.getNode(), "user input"

/**
 * @name Path traversal vulnerability
 * @description User input flowing into file system operations without proper validation
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // File system operations that take path arguments
    exists(API::CallNode call |
      (
        // os module file operations
        call = API::moduleImport("os").getMember(["open", "remove", "unlink", "rename", "stat", "lstat", "chmod", "chown", "utime"]).getACall() or
        call = API::moduleImport("os.path").getMember(["join", "exists", "isdir", "isfile", "islink"]).getACall() or
        call = API::moduleImport("builtins").getMember("open").getACall() or
        call = API::moduleImport("pathlib").getMember("Path").getACall() or
        call = API::moduleImport("shutil").getMember(["copy", "copyfile", "copytree", "move", "rmtree"]).getACall() or
        // aiohttp specific file operations
        call = API::moduleImport("aiohttp").getMember("web_fileresponse").getMember("FileResponse").getACall()
      ) and
      // Get the first argument (path) as a DataFlow::Node
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"

